def parse_query(qs: str) -> dict:
    """Parse a URL query string (without the leading '?') into a dict of lists."""

    _HEX = '0123456789abcdefABCDEF'

    def _decode(s: str) -> str:
        # '+' means space
        s = s.replace('+', ' ')
        if '%' not in s:
            return s
        out = bytearray()
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '%':
                if i + 2 >= n or s[i + 1] not in _HEX or s[i + 2] not in _HEX:
                    raise ValueError(
                        'malformed percent-escape at position %d: %r' % (i, s[i:i + 3])
                    )
                out.append(int(s[i + 1:i + 3], 16))
                i += 3
            else:
                out.extend(c.encode('utf-8'))
                i += 1
        return out.decode('utf-8', errors='replace')

    result = {}
    if not qs:
        return result

    for pair in qs.split('&'):
        if pair == '':
            continue  # empty pairs from '&&' or trailing '&'
        if '=' in pair:
            raw_key, raw_val = pair.split('=', 1)
        else:
            raw_key, raw_val = pair, ''
        key = _decode(raw_key)
        val = _decode(raw_val)
        if key in result:
            result[key].append(val)
        else:
            result[key] = [val]

    return result
```

Notes: the key is split at the first `=`, so later `=` characters stay in the value; percent-escapes are decoded byte-wise and then interpreted as UTF-8; a `%` not followed by exactly two hex digits raises `ValueError`.
